<?php require 'admin_bootstrap.php'; $title='Audit Log'; $q=$pdo->query("SELECT th.*,u.name,u.role FROM transaction_history th LEFT JOIN users u ON u.id=th.user_id ORDER BY th.created_at DESC LIMIT 200");$rows=$q->fetchAll(); require 'header.php'; admin_flash_html(); ?><section class="section"><div class="section-intro"><div><span class="eyebrow">ADMINISTRATION</span><h2>Audit Log</h2><p class="muted">A chronological record of important enrollment, ticket, and system actions.</p></div></div><div class="table-scroll"><table class="table"><tr><th>Date / Time</th><th>User</th><th>Action</th><th>Description</th></tr><?php foreach($rows as $r):?><tr><td><?=date('M d, Y g:i A',strtotime($r['created_at']))?></td><td><b><?=e($r['name']?:'System')?></b><br><small><?=e(ucfirst($r['role']?:''))?></small></td><td><?=e($r['action'])?></td><td><?=e($r['description'])?></td></tr><?php endforeach;?></table></div></section><?php require 'footer.php'; ?>
